from __future__ import annotations
from typing import Callable, TypeVar
import reactive.signal as sig

T = TypeVar('T')

def batch(fn: Callable[[], T]) -> T:
    sig._BATCH_DEPTH += 1
    try:
        return fn()
    finally:
        sig._BATCH_DEPTH -= 1
        if sig._BATCH_DEPTH == 0:
            effects = list(sig._PENDING_EFFECTS)
            sig._PENDING_EFFECTS.clear()
            for eff in effects:
                eff._run()

